// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StandardToken {
    function owner() external view returns (address);
    function forbidMint() external;
    function MINT_FORBIDDEN() external view returns (bool);
    function mint(address _who, uint256 _value) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we just need to impersonate the owner
        address owner = StandardToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner
        address owner = StandardToken(TARGET).owner();

        // Step 2: Impersonate the owner and call forbidMint()
        vm.prank(owner);
        StandardToken(TARGET).forbidMint();

        // Step 3: Verify that MINT_FORBIDDEN is now true
        bool mintForbidden = StandardToken(TARGET).MINT_FORBIDDEN();
        require(mintForbidden == true, "MINT_FORBIDDEN should be true after calling forbidMint()");

        // The vulnerability is demonstrated: state changed without event emission
        // We can also try to mint to confirm minting is disabled
        vm.prank(owner);
        vm.expectRevert("mint is forbidden forever. sorry");
        StandardToken(TARGET).mint(address(this), 100 ether);
        assertEq(mintForbidden, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

